import{z as A,x as B,o as s,c as d,q as t,j as i,D as e,d as E,s as n,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"业务逻辑漏洞","description":"","frontmatter":{"title":"业务逻辑漏洞","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/business-logic-flaws.md","filePath":"cs/business-logic-flaws.md","lastUpdated":1791063341000}'),p={name:"cs/business-logic-flaws.md"};function c(h,a,m,D,u,f){const r=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=t('<h1 id="业务逻辑漏洞" tabindex="-1">业务逻辑漏洞 <a class="header-anchor" href="#业务逻辑漏洞" aria-label="Permalink to &quot;业务逻辑漏洞&quot;">​</a></h1><div class="epigraph"><p>每一步都合法，合起来却破坏不变量：负数量、跳过支付、改价接口未授权。工具难自动找，因为错误在规格里，不在越界里。</p><footer>—— 据 OWASP 业务逻辑；Anderson 对激励与规则；对照[最小特权](/cs/acl-least-priv)</footer></div><p>上一课<a href="/cs/web-race-condition">竞态</a>的洞出在时间上：并发打乱了不变量。本课的洞出在<strong>规格本身</strong>：每步都合法，走完工作流，不变量却碎了。方法是把不变量显式写成测试；不给欺诈剧本。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个典型。价格：优惠接口各自打折、无总额下限，叠加出负价，退款再按负数继续走。状态机：未支付订单也能调「发货」端点，端点只查登录、没查前置条件。对象：改价接口信任客户端提交的金额，谁拿到请求模板谁就能改价。共同缺口：状态机只活在实现者脑子里、计价能被客户端影响、授权只在登录做了一次而不是每步都做。</p><p><span class="marginnote">数字实例：两张 9 折券叠一张满 100 减 20——100 元订单变成 100×0.9×0.9−20=61 元；若系统再不设总额下限，再叠一张「减 80」就得出负价，退款按负数走，反而给用户账户打钱。</span></p><h3 id="客体级授权" tabindex="-1">客体级授权 <a class="header-anchor" href="#客体级授权" aria-label="Permalink to &quot;客体级授权&quot;">​</a></h3><p>能调用 API 不等于能碰这一笔订单：授权要落到对象实例——是不是当前用户的订单——而非接口存在。BOLA 后课专收。</p><p><span class="marginnote">OWASP。禁止欺诈操作指导。撞库下一课是认证面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把不变量显式列出：价格非负、金额只在服务器算、状态沿状态机单向走、每个对象有属主且每请求核对。再把它们写成属性测试：随机生成操作序列，断言不变量在任意序列后仍成立——单步用例对组合漏洞无效，洞只在组合里。下一课撞库与速率。</p><p><span class="marginnote">直觉类比：不变量像游戏物理引擎——玩家每个按键都合法（每个 API 调用都过校验），但两键同按、按错顺序就能穿墙；漏洞藏在引擎允许的组合里，单看任一按键都看不出问题。</span></p>',13)),(s(),i(o,null,{default:e(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E5%8D%95%E6%AD%A5%E5%90%88%E6%B3%95%22%5D%20--%3E%20COMP%5B%22%E7%BB%84%E5%90%88%E7%A0%B4%E5%9D%8F%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%0A%20%20INV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%BE%A7%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20--%3E%20ENF%5B%22%E6%AF%8F%E8%AF%B7%E6%B1%82%E5%BC%BA%E5%88%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[E("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"为什么工具盲：扫描器与模糊测试盯的是「越界」——非法输入、注入、溢出；业务逻辑漏洞的每个输入都合法、都能过校验，坏在合起来的顺序与组合，规格之外的机器看不见规格里的洞。防线因此是让规格显式化：状态机由服务器强制，前端校验只做体验、不能当守门员；计价只认服务器数据；授权矩阵覆盖工作流每一步而不只在登录。撞库是另一条线：凭证已在别处泄漏，攻击者到你这里重放——那是认证面，下一课讲。",-1)),(s(),i(o,null,{default:e(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CREATE%5B%22%E5%88%9B%E5%BB%BA%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20C1%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%3A%20%E7%94%9F%E6%88%90%E9%87%91%E9%A2%9D%E5%B9%B6%E8%AE%B0%E5%B1%9E%E4%B8%BB%22%5D%0A%20%20C1%20--%3E%20PAY%5B%22%E6%94%AF%E4%BB%98%22%5D%0A%20%20PAY%20--%3E%20C2%5B%22%E6%A0%B8%E5%AF%B9%E5%B7%B2%E6%94%AF%E4%BB%98%E4%B8%8E%E5%AE%9E%E4%BB%98%E9%87%91%E9%A2%9D%22%5D%0A%20%20C2%20--%3E%20SHIP%5B%22%E5%8F%91%E8%B4%A7%E7%AB%AF%E7%82%B9%22%5D%0A%20%20SHIP%20--%3E%20C3%5B%22%E6%A0%A1%E9%AA%8C%E7%8A%B6%E6%80%81%E6%9C%BA%E5%89%8D%E7%BD%AE%2C%20%E6%8B%92%E7%BB%9D%E8%B7%B3%E6%AD%A5%22%5D%0A%20%20C3%20--%3E%20DONE%5B%22%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：初学者容易以为前端校验过了就安全——前端只做体验提示，攻击者拿请求工具直接重发即可绕过；金额、状态、属主三个判断必须在服务器每个请求重做。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写欺诈操作的具体步骤。一条要钉死：状态机不变量必须在服务器强制，不能只在前端。撞库与速率限制下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞态是时间；业务逻辑是规格。</li><li>不变量必须服务器强制。</li><li>工具对这类洞盲。</li><li>下一课撞库。</li><li>出处：OWASP Business Logic；Anderson；<a href="/cs/acl-least-priv">acl-least-priv</a>。</li></ul>',5))])}const b=A(p,[["render",c]]);export{P as __pageData,b as default};
